session_start();require 'config.php';$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$e=trim($_POST['email']??'');$p=$_POST['password']??'';$s=$conn->prepare('SELECT id,password_hash FROM users WHERE email=?');$s->bind_param('s',$e);$s->execute();$u=$s->get_result()->fetch_assoc();if($u&&password_verify($p,$u['password_hash'])){$_SESSION['user_id']=$u['id'];header('Location: index.php');exit;}$msg='ایمیل یا رمز عبور اشتباه است.';}?><!doctype html><html lang='fa' dir='rtl'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>ورود</title><link rel='stylesheet' href='style.css'></head><body><main class='formbox'><h1>🔐 ورود</h1><p class='error'><?=htmlspecialchars($msg)?></p><form method='post'><input name='email' type='email' placeholder='ایمیل' required><input name='password' type='password' placeholder='رمز عبور' required><button class='btn'>ورود</button></form><a href='register.php'>ساخت حساب جدید</a></main></body></html>